import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** One row of the `jobs` table, as stored. Internal fields (seq, idempotency_key, retry_at) never leave the server. */
export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  completed: number;
  output: string | null;
  error: string | null;
  idempotency_key: string | null;
  /** Epoch milliseconds before which a queued job must not be claimed (retry back-off). */
  retry_at: number;
  created_at: string;
  updated_at: string;
}

const SCHEMA = `
CREATE TABLE IF NOT EXISTS jobs (
  seq INTEGER PRIMARY KEY AUTOINCREMENT,
  id TEXT NOT NULL UNIQUE,
  status TEXT NOT NULL CHECK (status IN ('queued', 'running', 'completed', 'failed')),
  input TEXT NOT NULL,
  steps INTEGER NOT NULL,
  fail_attempts INTEGER NOT NULL,
  attempts INTEGER NOT NULL DEFAULT 0,
  completed INTEGER NOT NULL DEFAULT 0,
  output TEXT,
  error TEXT,
  idempotency_key TEXT UNIQUE,
  retry_at INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS jobs_status_seq ON jobs (status, seq);
CREATE TABLE IF NOT EXISTS worker_heartbeat (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  beat_at INTEGER NOT NULL
);
`;

/** Opens the SQLite database shared by the server and worker processes and makes sure the schema exists. */
export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;');
  db.exec(SCHEMA);
  return db;
}

/** Runs `fn` inside a short write transaction. Never await inside `fn`. */
export function inTransaction<T>(db: DatabaseSync, fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  let result: T;
  try {
    result = fn();
    db.exec('COMMIT');
  } catch (err) {
    try {
      db.exec('ROLLBACK');
    } catch {
      // no transaction was open
    }
    throw err;
  }
  return result;
}

export function prepareQueries(db: DatabaseSync) {
  return {
    insertJob: db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed, output, error, idempotency_key, retry_at, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, NULL, NULL, ?, 0, ?, ?)`,
    ),
    jobById: db.prepare('SELECT * FROM jobs WHERE id = ?'),
    jobByKey: db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?'),
    listJobs: db.prepare('SELECT * FROM jobs ORDER BY seq DESC'),
    nextQueued: db.prepare(`SELECT * FROM jobs WHERE status = 'queued' AND retry_at <= ? ORDER BY seq ASC LIMIT 1`),
    claim: db.prepare(
      `UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, output = NULL, error = NULL, updated_at = ? WHERE seq = ?`,
    ),
    progress: db.prepare('UPDATE jobs SET completed = ?, updated_at = ? WHERE seq = ?'),
    complete: db.prepare(
      `UPDATE jobs SET status = 'completed', completed = ?, output = ?, error = NULL, updated_at = ? WHERE seq = ?`,
    ),
    requeue: db.prepare(`UPDATE jobs SET status = 'queued', completed = 0, retry_at = ?, updated_at = ? WHERE seq = ?`),
    fail: db.prepare(
      `UPDATE jobs SET status = 'failed', completed = 0, output = NULL, error = 'transient failure', updated_at = ? WHERE seq = ?`,
    ),
    // Interrupted running jobs become queued again. An interrupted third attempt is rewound so that
    // its re-claim reuses attempt number 3 instead of starting a fourth attempt.
    recoverRunning: db.prepare(
      `UPDATE jobs SET status = 'queued', completed = 0, retry_at = 0,
         attempts = CASE WHEN attempts >= 3 THEN attempts - 1 ELSE attempts END, updated_at = ?
       WHERE status = 'running'`,
    ),
    heartbeat: db.prepare(
      'INSERT INTO worker_heartbeat (id, beat_at) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET beat_at = excluded.beat_at',
    ),
    lastHeartbeat: db.prepare('SELECT beat_at FROM worker_heartbeat WHERE id = 1'),
    clearHeartbeat: db.prepare('DELETE FROM worker_heartbeat WHERE id = 1'),
  };
}

export type Queries = ReturnType<typeof prepareQueries>;

