import type { JobRow, JobStatus } from './db.ts';

export interface FieldError {
  field: string;
  message: string;
}

/** The public job shape returned by every endpoint that returns a job. */
export interface PublicJob {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export interface Submission {
  input: string;
  steps: number;
  failAttempts: number;
  idempotencyKey: string | null;
}

export type SubmissionResult = { ok: true; value: Submission } | { ok: false; errors: FieldError[] };

const KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;
const KNOWN_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const DEFAULT_STEPS = 5;
const DEFAULT_FAIL_ATTEMPTS = 0;

export function toJob(row: JobRow): PublicJob {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.completed, total: row.steps },
    result: row.status === 'completed' && row.output !== null ? { output: row.output } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

/** Accepts `application/json` with any parameters, compared case-insensitively. */
export function isJsonContentType(contentType: string | undefined): boolean {
  if (contentType === undefined) return false;
  return contentType.split(';')[0]!.trim().toLowerCase() === 'application/json';
}

/**
 * Validates a submission and collects every problem rather than stopping at the first.
 * `body` is undefined when the body could not be read (for example, it exceeded the size limit).
 */
export function validateSubmission(opts: {
  contentType: string | undefined;
  body: string | undefined;
  idempotencyKey: string | undefined;
}): SubmissionResult {
  const errors: FieldError[] = [];
  let obj: Record<string, unknown> | undefined;

  if (!isJsonContentType(opts.contentType)) {
    errors.push({ field: 'body', message: 'Content-Type must be application/json.' });
  } else if (opts.body === undefined) {
    errors.push({ field: 'body', message: 'Request body is missing or too large.' });
  } else {
    let parsed: unknown;
    let parsedOk = true;
    try {
      parsed = JSON.parse(opts.body);
    } catch {
      parsedOk = false;
      errors.push({ field: 'body', message: 'Request body must be valid JSON.' });
    }
    if (parsedOk) {
      if (typeof parsed === 'object' && parsed !== null && !Array.isArray(parsed)) {
        obj = parsed as Record<string, unknown>;
      } else {
        errors.push({ field: 'body', message: 'Request body must be a JSON object.' });
      }
    }
  }

  let input = '';
  let steps = DEFAULT_STEPS;
  let failAttempts = DEFAULT_FAIL_ATTEMPTS;

  if (obj) {
    const has = (k: string) => Object.prototype.hasOwnProperty.call(obj, k);
    for (const key of Object.keys(obj)) {
      if (!KNOWN_FIELDS.has(key)) errors.push({ field: key, message: 'Unknown field.' });
    }

    if (!has('input')) {
      errors.push({ field: 'input', message: 'input is required.' });
    } else {
      const v = obj.input;
      if (typeof v !== 'string') errors.push({ field: 'input', message: 'input must be a string.' });
      else if (v.length < 1 || v.length > 1000) errors.push({ field: 'input', message: 'input must be 1 to 1000 characters.' });
      else if (v.trim() === '') errors.push({ field: 'input', message: 'input must not be only whitespace.' });
      else input = v;
    }

    const intField = (name: 'steps' | 'failAttempts', min: number, max: number, def: number): number => {
      if (!has(name)) return def;
      const v = obj![name];
      if (typeof v !== 'number' || !Number.isInteger(v) || v < min || v > max) {
        errors.push({ field: name, message: `${name} must be an integer from ${min} to ${max}.` });
        return def;
      }
      return v;
    };
    steps = intField('steps', 1, 20, DEFAULT_STEPS);
    failAttempts = intField('failAttempts', 0, 5, DEFAULT_FAIL_ATTEMPTS);
  }

  const key = opts.idempotencyKey;
  if (key !== undefined && !KEY_PATTERN.test(key)) {
    errors.push({
      field: 'Idempotency-Key',
      message: 'Idempotency-Key must be 1 to 128 characters: letters, digits, "_" or "-".',
    });
  }

  if (errors.length > 0) return { ok: false, errors };
  return { ok: true, value: { input, steps, failAttempts, idempotencyKey: key ?? null } };
}

