import { setInterval as every, clearInterval } from 'node:timers';
import { setTimeout as sleep } from 'node:timers/promises';
import { inTransaction, openDatabase, prepareQueries, type JobRow } from './db.ts';

const HEARTBEAT_EVERY_MS = 500;
const IDLE_POLL_MS = 100;
const STEP_MS = 100;
const MAX_ATTEMPTS = 3;
const RETRY_DELAY_MS = 500;

const db = openDatabase();
const q = prepareQueries(db);
let stopping = false;

function beat(): void {
  try {
    q.heartbeat.run(Date.now());
  } catch (err) {
    console.error('heartbeat failed:', err instanceof Error ? err.message : err);
  }
}

/** Atomically takes the oldest queued job whose retry deadline has passed and starts an attempt on it. */
function claimNext(): JobRow | undefined {
  return inTransaction(db, () => {
    const row = q.nextQueued.get(Date.now()) as JobRow | undefined;
    if (!row) return undefined;
    const now = new Date().toISOString();
    q.claim.run(now, row.seq);
    return { ...row, status: 'running', attempts: row.attempts + 1, completed: 0, output: null, error: null, updated_at: now };
  });
}

/** Rewinds jobs left `running` by a previous worker so they are claimed again. Terminal and queued jobs are untouched. */
function recoverInterrupted(): number {
  return inTransaction(db, () => q.recoverRunning.run(new Date().toISOString()).changes as number);
}

function failAttempt(job: JobRow, attempt: number): void {
  const now = new Date().toISOString();
  if (attempt < MAX_ATTEMPTS) {
    inTransaction(db, () => q.requeue.run(Date.now() + RETRY_DELAY_MS, now, job.seq));
  } else {
    inTransaction(db, () => q.fail.run(now, job.seq));
  }
}

async function runAttempt(job: JobRow): Promise<void> {
  const attempt = job.attempts;
  const simulatedFailure = attempt <= job.fail_attempts;
  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (step === 1 && simulatedFailure) {
      failAttempt(job, attempt);
      return;
    }
    const now = new Date().toISOString();
    if (step === job.steps) {
      // The final increment, the completed status, and the output are written in one statement.
      inTransaction(db, () => q.complete.run(step, job.input.toUpperCase(), now, job.seq));
    } else {
      q.progress.run(step, now, job.seq);
    }
  }
}

function clearHeartbeat(): void {
  try {
    q.clearHeartbeat.run();
  } catch {
    // best effort: the heartbeat simply expires
  }
}

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

beat();
const heartbeatTimer = every(beat, HEARTBEAT_EVERY_MS);

const recovered = recoverInterrupted();
console.log(`worker started (recovered ${recovered} interrupted job(s))`);

while (!stopping) {
  let job: JobRow | undefined;
  try {
    job = claimNext();
  } catch (err) {
    console.error('claim failed:', err instanceof Error ? err.message : err);
  }
  if (!job) {
    await sleep(IDLE_POLL_MS);
    continue;
  }
  try {
    await runAttempt(job);
  } catch (err) {
    console.error(`attempt on job ${job.id} failed:`, err instanceof Error ? err.message : err);
  }
}

clearInterval(heartbeatTimer);
clearHeartbeat();
db.close();
console.log('worker stopped');

