import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { inTransaction, openDatabase, prepareQueries, type JobRow } from './db.ts';
import { toJob, validateSubmission, type FieldError, type PublicJob } from './jobs.ts';

const db = openDatabase();
const q = prepareQueries(db);
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const HEARTBEAT_MAX_AGE_MS = 3_000;
const MAX_BODY_BYTES = 1024 * 1024;
const FORCE_CLOSE_AFTER_MS = 3_000;
const EXIT_AFTER_MS = 6_000;

function sendJson(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[], headers?: Record<string, string>): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  sendJson(res, status, { error }, headers);
}

/** Reads the whole body, or reports that it exceeded the limit. */
function readBody(req: IncomingMessage): Promise<string | undefined> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      if (tooLarge) return;
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        tooLarge = true;
        chunks.length = 0;
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? undefined : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

function findJob(id: string): JobRow | undefined {
  return q.jobById.get(id) as JobRow | undefined;
}

type Route = { kind: 'home' } | { kind: 'health' } | { kind: 'jobs' } | { kind: 'job'; id: string };

function matchRoute(pathname: string): Route | undefined {
  if (pathname === '/') return { kind: 'home' };
  if (pathname === '/health') return { kind: 'health' };
  if (pathname === '/api/jobs') return { kind: 'jobs' };
  const m = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (m) {
    let id = m[1]!;
    try {
      id = decodeURIComponent(id);
    } catch {
      // keep the raw segment; it will simply not match a job
    }
    return { kind: 'job', id };
  }
  return undefined;
}

function handleHealth(res: ServerResponse): void {
  const row = q.lastHeartbeat.get() as { beat_at: number } | undefined;
  const up = row !== undefined && row.beat_at > 0 && Date.now() - row.beat_at <= HEARTBEAT_MAX_AGE_MS;
  sendJson(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const body = await readBody(req);
  const header = req.headers['idempotency-key'];
  const result = validateSubmission({
    contentType: req.headers['content-type'],
    body,
    idempotencyKey: header,
  });
  if (!result.ok) {
    sendError(res, 400, 'invalid_request', 'The submitted job is invalid.', result.errors);
    return;
  }
  const v = result.value;

  const outcome = inTransaction(db, () => {
    if (v.idempotencyKey !== null) {
      const existing = q.jobByKey.get(v.idempotencyKey) as JobRow | undefined;
      if (existing) {
        const same = existing.input === v.input && existing.steps === v.steps && existing.fail_attempts === v.failAttempts;
        return same ? { kind: 'replay' as const, job: existing } : { kind: 'conflict' as const };
      }
    }
    const id = randomUUID();
    const now = new Date().toISOString();
    q.insertJob.run(id, v.input, v.steps, v.failAttempts, v.idempotencyKey, now, now);
    const created: JobRow = {
      seq: 0,
      id,
      status: 'queued',
      input: v.input,
      steps: v.steps,
      fail_attempts: v.failAttempts,
      attempts: 0,
      completed: 0,
      output: null,
      error: null,
      idempotency_key: v.idempotencyKey,
      retry_at: 0,
      created_at: now,
      updated_at: now,
    };
    return { kind: 'created' as const, job: created };
  });

  if (outcome.kind === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  } else if (outcome.kind === 'replay') {
    sendJson(res, 200, toJob(outcome.job));
  } else {
    sendJson(res, 201, toJob(outcome.job));
  }
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const method = req.method ?? 'GET';
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const route = matchRoute(pathname);
  if (!route) {
    sendError(res, 404, 'not_found', 'No such route.');
    return;
  }

  const allowed = route.kind === 'jobs' ? ['GET', 'POST'] : ['GET'];
  if (!allowed.includes(method)) {
    sendError(res, 405, 'method_not_allowed', `Method ${method} is not allowed on this route.`, undefined, { allow: allowed.join(', ') });
    return;
  }

  switch (route.kind) {
    case 'home':
      res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
      res.end(uiHtml);
      return;
    case 'health':
      handleHealth(res);
      return;
    case 'jobs':
      if (method === 'POST') return handleCreate(req, res);
      sendJson(res, 200, { jobs: (q.listJobs.all() as unknown as JobRow[]).map(toJob) });
      return;
    case 'job': {
      const row = findJob(route.id);
      if (!row) sendError(res, 404, 'not_found', 'No job with that id.');
      else sendJson(res, 200, toJob(row));
      return;
    }
  }
}

const server = createServer((req, res) => {
  handle(req, res).catch((err: unknown) => {
    console.error('request failed:', err instanceof Error ? err.message : err);
    if (res.headersSent) {
      res.end();
    } else {
      sendError(res, 500, 'internal_error', 'Unexpected server error.');
    }
  });
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));

let shuttingDown = false;
function shutdown(signal: NodeJS.Signals): void {
  if (shuttingDown) return;
  shuttingDown = true;
  console.log(`server stopping (${signal})`);
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeIdleConnections();
  setTimeout(() => server.closeAllConnections(), FORCE_CLOSE_AFTER_MS).unref();
  setTimeout(() => process.exit(1), EXIT_AFTER_MS).unref();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

