const v9 = await post({ input: 'x', steps: 21 });
check('steps 21 rejected', v9.status === 400, v9);
const u = await fetch(base + '/api/jobs/abc', { method: 'DELETE' });
check('DELETE /api/jobs/:id 405 json', u.status === 405 && (await u.json()).error.code === 'method_not_allowed');
const nf = await get('/api/jobs/does-not-exist');
